query FindManyInitiatives($filter: InitiativeFilterInput, $orderBy: [InitiativeOrderByInput], $lastCursor: String, $limit: Int, $offset: Int) {
  initiatives(
    filter: $filter
    orderBy: $orderBy
    first: $limit
    after: $lastCursor
    offset: $offset
  ) {
    edges {
      node {
        __typename
        createdAt
        createdBy {
          source
          workspaceMemberId
          name
          context {
            provider
            applicationId
            __typename
          }
          __typename
        }
        deletedAt
        id
        name
        position
        updatedAt
        updatedBy {
          source
          workspaceMemberId
          name
          context {
            provider
            applicationId
            __typename
          }
          __typename
        }
      }
      cursor
      __typename
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
      __typename
    }
    totalCount
    __typename
  }
}
